// Test scenario 1 (docs/superpowers/plans/test-set.md): an online retail base built through the interface, in English —
// tables, 1,000 order lines generated by action queries, a data entry form, a sales report and an invoice as PDF.
// Previous run's files are deleted first; this run's files stay in OUT for inspection.
import { test, expect, type Page } from '@playwright/test';
import { mkdirSync, readFileSync, renameSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import type { BasecraftApi } from '../../src/shared/api';
import { launchApp } from './helpers';

const OUT = join(tmpdir(), 'basecraft-scenarios', 'test1');
const PDF_PATH = join(OUT, 'export.pdf');
const EN = { BASECRAFT_REGION: 'en-US' };
type Win = { basecraft: BasecraftApi };
const doc = (page: Page) => page.locator('section[role=tabpanel]:not([hidden]), .doc:not([hidden])').first();
const count = (page: Page, t: string) => page.evaluate((n) => (window as unknown as Win).basecraft.rows.count(n), t);

const TABLES: [string, [string, string][]][] = [
  ['Customers', [['ID', 'autoNumber'], ['Name', 'shortText'], ['City', 'shortText']]],
  ['Products', [['ID', 'autoNumber'], ['Name', 'shortText'], ['PurchasePrice', 'currency'], ['SalePrice', 'currency']]],
  ['Orders', [['ID', 'autoNumber'], ['CustomerID', 'number'], ['OrderDate', 'dateTime'], ['DeliveryDate', 'dateTime']]],
  ['OrderLines', [['ID', 'autoNumber'], ['OrderID', 'number'], ['ProductID', 'number'], ['Quantity', 'number'], ['UnitPrice', 'currency']]],
];
const CUSTOMERS = [['Alice Martin', 'Boston'], ['Bob Chen', 'Austin'], ['Carla Diaz', 'Denver'], ['David Kim', 'Seattle'], ['Emma Rossi', 'Chicago'],
  ['Farid Haddad', 'Boston'], ['Grace Lee', 'Austin'], ['Hugo Weber', 'Denver'], ['Ines Silva', 'Seattle'], ['Jack Brown', 'Chicago']];
const PRODUCTS: [string, number, number][] = [['USB-C Cable', 2.1, 9.99], ['Wireless Mouse', 8.5, 24.9], ['Keyboard', 15, 49], ['27" Monitor', 140, 249],
  ['Webcam HD', 22, 59.5], ['Headset', 30, 79], ['Laptop Stand', 12, 34.99], ['Desk Lamp', 9.8, 29.9], ['Power Bank', 11, 39], ['SSD 1 TB', 48, 89.9],
  ['HDMI Cable', 1.6, 7.5], ['Mouse Pad', 1.2, 6.99], ['Docking Station', 70, 159], ['Microphone', 35, 99], ['Router', 40, 119],
  ['Smart Plug', 6, 19.9], ['Speaker', 25, 69], ['Tablet Case', 5, 24], ['Charger 65 W', 14, 39.9], ['Memory Card', 4.5, 15.9]];

async function newTable(page: Page, name: string, fields: [string, string][]) {
  await page.getByTestId('ribbon-tab-create').click();
  await page.getByTestId('cmd-createTableDesign').click();
  await expect(page.getByTestId('doc-tab-Table1')).toBeVisible();
  for (const [i, [n, type]] of fields.entries()) {
    await page.getByTestId(`design-row-${i}-name`).fill(n);
    await page.getByTestId(`design-row-${i}-type`).selectOption(type);
  }
  await page.keyboard.press('Control+s');
  await page.getByTestId('modal-input').fill(name);
  await page.getByTestId('modal-btn-ok').click();
  await expect(page.getByTestId(`nav-item-${name}`)).toBeVisible();
  await page.getByTestId(`doc-tab-close-${name}`).click();
}
/** Runs the SQL in the open SQL view: action queries ask to confirm their rows, Yes. */
async function runAction(page: Page, sql: string) {
  await doc(page).getByTestId('query-sql').fill(sql);
  try {
    await expect(page.getByTestId('cmd-runQuery'), sql).toBeEnabled({ timeout: 5000 });
  } catch (e) {
    await page.screenshot({ path: join(OUT, 'run-disabled.png') });
    throw e;
  }
  await page.getByTestId('cmd-runQuery').click();
  await page.getByTestId('modal-btn-yes').click();
  await expect(page.getByTestId('modal')).toHaveCount(0);
}
async function newSqlQuery(page: Page) {
  await page.getByTestId('ribbon-tab-create').click();
  await page.getByTestId('cmd-createSqlQuery').click();
  await expect(doc(page).getByTestId('query-sql')).toBeVisible();
}
async function saveAs(page: Page, kind: string, name: string) {
  await page.keyboard.press('Control+s');
  await page.getByTestId('modal-input').fill(name);
  await page.getByTestId('modal-btn-ok').click();
  await expect(page.getByTestId(`nav-item-${kind}-${name}`)).toBeVisible();
}
async function autoReport(page: Page, source: string) {
  await page.getByTestId('ribbon-tab-create').click();
  await page.getByTestId('cmd-createReport').click();
  await page.getByTestId('source-picker-list').selectOption(source);
  await page.getByTestId('source-picker-ok').click();
  await expect(doc(page).getByTestId('preview-page-of')).toBeVisible();
}
/** Exports the previewed report (the e2e hook writes PDF_PATH), then gives the file its name. */
async function exportPdf(page: Page, name: string) {
  await page.getByTestId('cmd-exportPdf').click();
  await page.getByTestId('modal-btn-ok').click();
  renameSync(PDF_PATH, join(OUT, name));
  expect(readFileSync(join(OUT, name)).subarray(0, 5).toString()).toBe('%PDF-');
}

test('scenario 1: online retail base, 1,000 order lines, entry form, sales report and invoice', async () => {
  test.setTimeout(600_000);
  rmSync(OUT, { recursive: true, force: true });
  mkdirSync(OUT, { recursive: true });
  const base = join(OUT, 'Retail.basecraft');
  const userDataDir = join(OUT, 'userdata');
  mkdirSync(userDataDir);
  writeFileSync(join(userDataDir, 'settings.json'), JSON.stringify({ locale: 'en' }));
  const timings: Record<string, number> = {};
  let t0 = Date.now();
  const lap = (k: string) => { timings[k] = Date.now() - t0; t0 = Date.now(); };

  const { app, page } = await launchApp({ env: { ...EN, BASECRAFT_E2E_SAVE_PATH: base, BASECRAFT_E2E_PDF_PATH: PDF_PATH }, userDataDir });
  try {
    // 1. the base and its tables
    await page.getByTestId('bs-new').click();
    await expect(page.getByTestId('nav-pane')).toBeVisible();
    for (const [name, fields] of TABLES) await newTable(page, name, fields);
    lap('tables');

    // 2. data: customers and products one row each, orders and lines generated by cross joins
    await newSqlQuery(page);
    for (const [n, c] of CUSTOMERS) await runAction(page, `INSERT INTO Customers (Name, City) VALUES ("${n}", "${c}")`);
    for (const [n, buy, sell] of PRODUCTS) await runAction(page, `INSERT INTO Products (Name, PurchasePrice, SalePrice) VALUES ("${n.replace(/"/g, '""')}", ${buy}, ${sell})`);
    await runAction(page, 'INSERT INTO Orders (CustomerID, OrderDate, DeliveryDate) '
      + 'SELECT Customers.ID, DateAdd("d", Customers.ID * 7 + Products.ID * 30, #2026-01-05#), DateAdd("d", Customers.ID * 7 + Products.ID * 30 + 2 + Products.ID Mod 4, #2026-01-05#) '
      + 'FROM Customers, Products WHERE Products.ID <= 5');
    await runAction(page, 'INSERT INTO OrderLines (OrderID, ProductID, Quantity, UnitPrice) '
      + 'SELECT Orders.ID, Products.ID, 1 + (Orders.ID * 3 + Products.ID * Products.ID) Mod 7, Products.SalePrice FROM Orders, Products');
    expect(await count(page, 'Customers')).toBe(10);
    expect(await count(page, 'Products')).toBe(20);
    expect(await count(page, 'Orders')).toBe(50);
    expect(await count(page, 'OrderLines')).toBe(1000);
    lap('data');

    // 3. the queries the reports read
    await doc(page).getByTestId('query-sql').fill('SELECT Products.Name AS Product, Sum(OrderLines.Quantity) AS Units, '
      + 'Sum(OrderLines.Quantity * OrderLines.UnitPrice) AS Revenue, Sum(OrderLines.Quantity * (OrderLines.UnitPrice - Products.PurchasePrice)) AS Margin '
      + 'FROM OrderLines INNER JOIN Products ON OrderLines.ProductID = Products.ID GROUP BY Products.Name ORDER BY Products.Name');
    await saveAs(page, 'query', 'QSalesByProduct');
    await newSqlQuery(page);
    await doc(page).getByTestId('query-sql').fill('SELECT Orders.ID AS OrderNo, Customers.Name AS Customer, Customers.City, Orders.OrderDate, Orders.DeliveryDate, '
      + 'Products.Name AS Product, OrderLines.Quantity, OrderLines.UnitPrice, OrderLines.Quantity * OrderLines.UnitPrice AS Amount '
      + 'FROM ((OrderLines INNER JOIN Orders ON OrderLines.OrderID = Orders.ID) INNER JOIN Customers ON Orders.CustomerID = Customers.ID) '
      + 'INNER JOIN Products ON OrderLines.ProductID = Products.ID WHERE Orders.ID = 1');
    await saveAs(page, 'query', 'QInvoice');
    lap('queries');

    // 4. the entry form on Orders: Form Design, fields from the Field List, then Form view and a new order
    await page.getByTestId('ribbon-tab-create').click();
    await page.getByTestId('cmd-createFormDesign').click();
    await expect(page.getByTestId('designer')).toBeVisible();
    await page.getByTestId('prop-RecordSource').fill('Orders');
    await page.getByTestId('prop-RecordSource').press('Enter');
    await page.getByTestId('cmd-addExistingFields').click();
    for (const f of ['ID', 'CustomerID', 'OrderDate', 'DeliveryDate']) {
      await page.getByTestId(`field-${f}`).dblclick();
      await expect(page.getByTestId(`ctl-${f}`)).toBeVisible();
    }
    await saveAs(page, 'form', 'OrderEntry');
    await page.getByTestId('cmd-viewForm').click();
    const ctl = (n: string) => page.getByTestId(`form-ctl-${n}`).filter({ visible: true });
    await expect(ctl('CustomerID')).toHaveValue('1');
    await page.getByTestId('nav-new').filter({ visible: true }).click();
    await ctl('CustomerID').fill('3');
    await ctl('OrderDate').fill('10/20/2026');
    await ctl('DeliveryDate').fill('10/24/2026');
    await page.keyboard.press('Shift+Enter');
    await expect.poll(() => count(page, 'Orders')).toBe(51);
    lap('form');

    // 5. sales report: AutoReport on the query (saved under the query's name), PDF
    await autoReport(page, 'query:QSalesByProduct');
    await expect(page.getByTestId('nav-item-report-QSalesByProduct')).toBeVisible();
    await page.screenshot({ path: join(OUT, 'sales-preview.png') });
    await exportPdf(page, 'SalesByProduct.pdf');
    // 6. invoice: AutoReport on QInvoice, grouped on OrderNo with a Sum of Amount in the group footer, PDF
    await autoReport(page, 'query:QInvoice');
    await page.getByTestId('ribbon-tab-home').click();
    await page.getByTestId('cmd-viewDesign').click();
    await page.getByTestId('ribbon-tab-reportDesign').click();
    await page.getByTestId('cmd-groupSort').click();
    await page.getByTestId('grouping-add-group').click();
    await page.getByTestId('grouping-field-OrderNo').click();
    await page.getByTestId('grouping-row-0-footer').selectOption('true');
    await doc(page).locator('.dz-block', { has: page.getByTestId('section-detail') }).getByTestId('ctl-Amount').click();
    await page.getByTestId('cmd-reportTotals').click();
    await page.getByTestId('totals-popup-Sum').click();
    await page.getByTestId('ribbon-tab-home').click();
    await page.getByTestId('cmd-save').click();
    await expect(page.getByTestId('doc-tab-report-QInvoice')).not.toContainText('•');
    await page.getByTestId('ribbon-tab-reportDesign').click();
    await page.getByTestId('cmd-viewPrintPreview').click();
    await expect(doc(page).getByTestId('preview-page-of')).toBeVisible();
    await page.screenshot({ path: join(OUT, 'invoice-preview.png') });
    await exportPdf(page, 'Invoice.pdf');
    lap('reports');
  } finally {
    writeFileSync(join(OUT, 'timings.json'), JSON.stringify(timings, null, 2));
    await app.close();
  }
});
